using System; using System.IO; using UnityEngine; namespace MyLumo { [Serializable] public class LumoSaveData { public int location; public float hunger,energy,happiness,hygiene,social; public OutfitState outfit; } public class GameStatePersistence:MonoBehaviour { public static GameStatePersistence Instance{get;private set;} public LumoController lumo; string P=>Path.Combine(Application.persistentDataPath,"my_lumo_save.json"); void Awake()=>Instance=this; void Start()=>Load(); public void SaveNow(){if(!lumo||!lumo.needs||!lumo.inventory)return;var d=new LumoSaveData{location=(int)lumo.currentLocation,hunger=lumo.needs.hunger.value,energy=lumo.needs.energy.value,happiness=lumo.needs.happiness.value,hygiene=lumo.needs.hygiene.value,social=lumo.needs.social.value,outfit=lumo.inventory.outfit};File.WriteAllText(P,JsonUtility.ToJson(d,true));} public void Load(){if(!File.Exists(P)||!lumo||!lumo.needs||!lumo.inventory)return;var d=JsonUtility.FromJson<LumoSaveData>(File.ReadAllText(P));lumo.currentLocation=(LumoLocation)d.location;lumo.needs.hunger.value=d.hunger;lumo.needs.energy.value=d.energy;lumo.needs.happiness.value=d.happiness;lumo.needs.hygiene.value=d.hygiene;lumo.needs.social.value=d.social;if(d.outfit!=null)lumo.inventory.outfit=d.outfit;} void OnApplicationPause(bool p){if(p)SaveNow();} void OnApplicationQuit()=>SaveNow(); } }
